window.VersionHistory={history:[],tooltipEl:null,init:function(){console.log("[VersionHistory] Plugin initialized."),this.createTooltip(),setTimeout(()=>{this.recordCurrentVersion(),this.attachHoverEvent()},500),document.addEventListener("fc-view-loaded",()=>{this.attachHoverEvent()})},recordCurrentVersion:function(){const t=window.flutcomApp?._cfg?.version||"Unknown",e=localStorage.getItem("flutcom_version_history");if(e)try{this.history=JSON.parse(e)}catch(t){this.history=[]}const o=this.history[this.history.length-1];o&&o.version===t||(this.history.push({version:t,date:(new Date).toLocaleDateString()}),localStorage.setItem("flutcom_version_history",JSON.stringify(this.history)))},createTooltip:function(){this.tooltipEl=document.createElement("div"),this.tooltipEl.className="version-history-tooltip",this.tooltipEl.style.cssText="\n      position: absolute;\n      background: #18181b; /* zinc-900 */\n      border: 1px solid #27272a; /* zinc-800 */\n      border-radius: 0.75rem;\n      padding: 1rem;\n      width: 220px;\n      z-index: 9999;\n      box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.5);\n      color: #d4d4d8; /* zinc-300 */\n      font-family: inherit;\n      opacity: 0;\n      pointer-events: none;\n      transform: translateY(10px);\n      transition: all 0.2s ease;\n    ",document.body.appendChild(this.tooltipEl)},renderHistory:function(){if(0===this.history.length)return'<div style="font-size: 0.875rem; color: #71717a;">No history yet.</div>';let t='<div style="font-size: 0.75rem; font-weight: bold; color: #fff; margin-bottom: 0.5rem; text-transform: uppercase; letter-spacing: 0.05em;">Version History</div>';return t+='<ul style="list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 0.5rem;">',[...this.history].reverse().forEach((e,o)=>{const i=0===o;t+=`\n        <li style="display: flex; align-items: center; justify-content: space-between; font-size: 0.875rem;">\n          <div style="display: flex; align-items: center; gap: 0.5rem;">\n            <span style="display: inline-block; width: 6px; height: 6px; border-radius: 50%; background: ${i?"#10b981":"#52525b"};"></span>\n            <span style="font-family: monospace; font-weight: ${i?"bold":"normal"}; color: ${i?"#fff":"#a1a1aa"};">v${e.version}</span>\n          </div>\n          <span style="font-size: 0.7rem; color: #71717a;">${e.date}</span>\n        </li>\n      `}),t+="</ul>",t},attachHoverEvent:function(){document.addEventListener("mouseover",t=>{const e=t.target.closest(".fc-version-badge");if(!e)return;this.recordCurrentVersion(),this.tooltipEl.innerHTML=this.renderHistory();const o=e.getBoundingClientRect();this.tooltipEl.style.top=`${o.bottom+10}px`,this.tooltipEl.style.left=o.left-(220-o.width)/2+"px",this.tooltipEl.style.opacity="1",this.tooltipEl.style.transform="translateY(0)",e.addEventListener("mouseleave",()=>{this.tooltipEl.style.opacity="0",this.tooltipEl.style.transform="translateY(10px)"},{once:!0})})}},window.VersionHistory.init();